/** Methods a complete HostKernel must implement, including the dot forms. */
export function hostMethodNames() {
    const names = [];
    for( const [name, row] of HOST_SURFACE )
    {
        names.push(name);
        if( row.dotCapable ) names.push(`dot_${name}`);
    }
    return names;
}
